mapper.select:
SELECT COUNT(*)
FROM md_datasource_resource
WHERE datasource_key = #{datasourceKey}

mapper.update:
UPDATE md_datasource_resource
SET active_operation_id = #{operationId}
WHERE datasource_key = #{datasourceKey}
AND status = 'REGISTERED'
AND is_deleted = 0
AND active_operation_id IS NULL

UPDATE md_datasource_resource
SET active_operation_id = NULL
WHERE datasource_key = #{datasourceKey}
AND active_operation_id = #{operationId}

mapper.select:
SELECT datasource_id, COUNT(*) AS total FROM md_datasource_table WHERE status = 'CREATED' AND datasource_id IN
#{id}
GROUP BY datasource_id

SELECT datasource_id, COUNT(*) AS total FROM md_datasource_resource WHERE status = 'REGISTERED' AND is_deleted = 0 AND datasource_id IN
#{id}
GROUP BY datasource_id
